import type {
  ToolbarProps,
  ToolbarItemProps,
  ToolbarDividerProps,
  ToolbarToggleGroupProps,
  ToolbarToggleItemProps,
  ToolbarGroupProps,
  ToolbarLeadingProps,
  ToolbarTrailingProps,
} from "./toolbar.types";

import { forwardRef, Children, isValidElement, cloneElement, useState, useCallback } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import * as RadixToolbar from "@radix-ui/react-toolbar";

import { Divider } from "../divider";
import { ButtonGroup } from "../button-group";
import { StyledToggleButton } from "../toggle-button/toggle-button.styles";

import { StyledToolbar, ToolbarClasses } from "./toolbar.styles";

const ToolbarRoot = forwardRef<HTMLDivElement, ToolbarProps>(
  ({ className, variant = "default", asChild, children, ...props }: ToolbarProps, ref) => {
    const theme = useTheme(),
      rootClasses = clsx(ToolbarClasses.root, className);

    return (
      <StyledToolbar
        ref={ref}
        asChild={asChild}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledToolbar>
    );
  },
);
ToolbarRoot.displayName = "Toolbar";

const ToolbarLeading = forwardRef<HTMLDivElement, ToolbarLeadingProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(ToolbarClasses.leading, className)} {...props}>
        {children}
      </div>
    );
  },
);
ToolbarLeading.displayName = "Toolbar.Leading";

const ToolbarTrailing = forwardRef<HTMLDivElement, ToolbarTrailingProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(ToolbarClasses.trailing, className)} {...props}>
        {children}
      </div>
    );
  },
);
ToolbarTrailing.displayName = "Toolbar.Trailing";

const ToolbarItem = forwardRef<HTMLButtonElement, ToolbarItemProps>(
  ({ className, asChild = true, children, ...props }, ref) => {
    const modifiedChildren = Children.map(children, (child) => {
      if (isValidElement(child)) {
        const displayName = (child.type as { displayName?: string })?.displayName;

        if (displayName === "Button") {
          return cloneElement(child, {
            variant: child.props.variant || "desaturated",
            buttonType: child.props.buttonType || "secondary",
          });
        } else if (displayName === "IconButton") {
          return cloneElement(child, {
            buttonType: child.props.buttonType || "secondary",
          });
        }
      }
      return child;
    });

    const childToRender =
      Array.isArray(modifiedChildren) && modifiedChildren.length === 1
        ? modifiedChildren[0]
        : modifiedChildren;

    return (
      <RadixToolbar.Button
        ref={ref}
        asChild={asChild}
        className={clsx(ToolbarClasses.item, className)}
        {...props}
      >
        {childToRender}
      </RadixToolbar.Button>
    );
  },
);
ToolbarItem.displayName = "Toolbar.Item";

const ToolbarDivider = forwardRef<HTMLDivElement, ToolbarDividerProps>(
  ({ className, ...props }, ref) => {
    return (
      <Divider
        ref={ref}
        className={clsx(ToolbarClasses.divider, className)}
        orientation="vertical"
        {...props}
      />
    );
  },
);
ToolbarDivider.displayName = "Toolbar.Divider";

const ToolbarToggleGroup = forwardRef<HTMLDivElement, ToolbarToggleGroupProps>(
  (
    { className, children, value: controlledValue, onValueChange, type, defaultValue, ...props },
    ref,
  ) => {
    const theme = useTheme();
    const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
    const isControlled = controlledValue !== undefined;
    const value = isControlled ? controlledValue : uncontrolledValue;

    const handleValueChange = useCallback(
      (newValue: string & string[]) => {
        if (type === "single" && newValue === "") {
          // Prevent deselection if type is "single" and the new value is empty
          return;
        }
        if (!isControlled) {
          setUncontrolledValue(newValue);
        }
        onValueChange?.(newValue);
      },
      [isControlled, onValueChange, type],
    );

    return (
      <RadixToolbar.ToggleGroup
        ref={ref}
        asChild
        className={clsx(ToolbarClasses.toggleGroup, className)}
        type={type}
        value={value as string & string[]}
        onValueChange={handleValueChange}
        {...props}
      >
        <StyledToggleButton currentTheme={theme}>{children}</StyledToggleButton>
      </RadixToolbar.ToggleGroup>
    );
  },
);
ToolbarToggleGroup.displayName = "Toolbar.ToggleGroup";

const ToolbarToggleItem = forwardRef<HTMLButtonElement, ToolbarToggleItemProps>(
  ({ className, asChild = true, ...props }, ref) => {
    return (
      <RadixToolbar.ToggleItem
        ref={ref}
        asChild={asChild}
        className={clsx(ToolbarClasses.toggleItem, className)}
        {...props}
      />
    );
  },
);
ToolbarToggleItem.displayName = "Toolbar.ToggleItem";

const ToolbarGroup = forwardRef<HTMLDivElement, ToolbarGroupProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <ButtonGroup ref={ref} className={clsx(ToolbarClasses.group, className)} {...props}>
        {children}
      </ButtonGroup>
    );
  },
);
ToolbarGroup.displayName = "Toolbar.Group";

const Toolbar = Object.assign(ToolbarRoot, {
  Leading: ToolbarLeading,
  Trailing: ToolbarTrailing,
  Item: ToolbarItem,
  Divider: ToolbarDivider,
  ToggleGroup: ToolbarToggleGroup,
  ToggleItem: ToolbarToggleItem,
  Group: ToolbarGroup,
});

export default Toolbar;
